def outlook_account(outlook, sender):
    matches = [
        account for account in outlook.Session.Accounts
        if (account.SmtpAddress or "").casefold() == sender.casefold()
    ]
    if len(matches) != 1:
        raise ValueError("Configured Outlook sender unavailable or ambiguous")
    return matches[0]


def send_outlook(config, message):
    import pythoncom
    import win32com.client

    pythoncom.CoInitializeEx(pythoncom.COINIT_APARTMENTTHREADED)
    outlook = account = mail = None
    try:
        outlook = win32com.client.GetActiveObject("Outlook.Application")
        account = outlook_account(outlook, config["sender"])
        mail = outlook.CreateItem(0)
        mail.SendUsingAccount = account
        if mail.SendUsingAccount.SmtpAddress.casefold() != config["sender"].casefold():
            raise ValueError("Outlook sender selection failed")
        for address in config["recipients"]:
            mail.Recipients.Add(address)
        if not mail.Recipients.ResolveAll():
            raise ValueError("Outlook recipient unresolved")
        mail.Subject = str(message["Subject"])
        body = message.get_body(preferencelist=("html", "plain"))
        if body.get_content_subtype() == "html":
            mail.HTMLBody = body.get_content()
        else:
            mail.Body = body.get_content()
        mail.Send()
    finally:
        mail = account = outlook = None
        pythoncom.CoUninitialize()
